using System;using System.IO;using System.Linq;using System.Collections;using System.Collections.Generic;using System.Reflection;using UnityEngine;using EchoSphere.Core;using EchoSphere.Runtime;
public static class RegionalAttackAcceptance {
 public static object Main(){if(!Application.isPlaying)throw new Exception("Play required");const BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public;var r=UnityEngine.Object.FindAnyObjectByType<EchoSphereRuntime>();var rt=r.GetType();var et=typeof(EnemyAgent2D);var bt=typeof(BossProjectileAgent2D);var agents=(List<MonoBehaviour>)rt.GetField("_simulationAgents",F).GetValue(r);var oldAgents=agents.ToArray();var types=(Dictionary<Type,List<MonoBehaviour>>)rt.GetField("_simulationTypes",F).GetValue(r);var oldTypes=types.ToDictionary(p=>p.Key,p=>p.Value.ToArray());bool menu=(bool)rt.GetField("_mainMenu",F).GetValue(r),paused=(bool)rt.GetField("_paused",F).GetValue(r);var go=new GameObject("Regional attack acceptance");var target=new GameObject("Isolated projectile target");go.transform.position=new Vector2(1000,1000);target.transform.position=new Vector2(5000,5000);var e=go.AddComponent<EnemyAgent2D>();var before=UnityEngine.Object.FindObjectsByType<BossProjectileAgent2D>().ToHashSet();int checks=0;
 void A(bool ok,string why){checks++;if(!ok)throw new Exception(why);}void Set(string n,object v)=>et.GetField(n,F).SetValue(e,v);void Tick(float dt,Vector2 aim)=>et.GetMethod("TickRegionalAttack",F).Invoke(e,new object[]{dt,aim,1f});
 try{Set("_runtime",r);rt.GetField("_mainMenu",F).SetValue(r,false);rt.GetField("_paused",F).SetValue(r,false);
 for(int region=0;region<6;region++){Set("_campaignRegionStyle",region);Set("_role","ranged");Set("_regionalCooldown",0f);Set("_regionalWindup",0f);var p=RegionalEnemyRules.Get(region,"ranged");int start=agents.Count;var aim=new Vector2(1010,1000);Tick(.01f,aim);A(agents.Count==start,"no shot before telegraph");Tick(p.Windup+.01f,new Vector2(1000,1010));var shots=agents.Skip(start).OfType<BossProjectileAgent2D>().ToArray();A(shots.Length==p.Pellets,"expected volley");foreach(var b in shots){var velocity=(Vector2)bt.GetField("_velocity",F).GetValue(b);A(velocity.x>0&&Mathf.Abs(velocity.y)<velocity.x*.5f,"aim fixed at windup, not homing");A((string)bt.GetField("_bossType",F).GetValue(b)=="regional_"+p.Shot,"regional projectile type");bt.GetField("_player",F).SetValue(b,target.transform);
 if(region==2){bt.GetField("_time",F).SetValue(b,.91f);b.SimulationTick(.01f);A(((Vector2)bt.GetField("_velocity",F).GetValue(b))==Vector2.zero,"spore becomes patch");A((float)bt.GetField("_hitRadius",F).GetValue(b)>BossCombatRules.PlayerRadiusWorld,"patch collision extent");}
 bt.GetField("_time",F).SetValue(b,5f);b.SimulationTick(.01f);A((bool)bt.GetField("_removed",F).GetValue(b),"bounded projectile lifetime");}
 int fired=agents.Count;Tick(.1f,aim);A(agents.Count==fired,"no repeated shot during cooldown");}
 var result=new{result="PASS",checks,scope="Actual Play Mode regional windup, locked aim, volleys, cooldown, spore patch and lifetime. No phone/balance/visual acceptance."};File.WriteAllText("Library/regional-attack-acceptance.json",JsonUtility.ToJson(new Record{result="PASS",checks=checks},true));return result;
 }finally{foreach(var b in UnityEngine.Object.FindObjectsByType<BossProjectileAgent2D>())if(!before.Contains(b))UnityEngine.Object.DestroyImmediate(b.gameObject);agents.Clear();agents.AddRange(oldAgents);types.Clear();foreach(var pair in oldTypes)types.Add(pair.Key,new List<MonoBehaviour>(pair.Value));rt.GetField("_mainMenu",F).SetValue(r,menu);rt.GetField("_paused",F).SetValue(r,paused);UnityEngine.Object.DestroyImmediate(go);UnityEngine.Object.DestroyImmediate(target);}
 }
 [Serializable]public class Record{public string result;public int checks;}
}
